et map"}, {"id": "269f3901-0ec0-4541-a011-29d33de9d019", "type": "concept", "title": "competitor scan"}, {"id": "bb890262-6e64-44a2-85d4-50935738c81a", "type": "concept", "title": "stakeholder map"}, {"id": "dd600310-a46b-469c-b084-4206a7c71576", "type": "concept", "title": "business model canvas"}], "description": "Why it matters: Students define the organization, audience, competitors, revenue model, and public-interest stakes."}, {"id": "d203231b-ae53-43b9-98aa-c1a6f003f1fd", "type": "subtopic", "title": "Technology and policy assessment", "children": [{"id": "920381f8-1b99-4979-8d5d-7339636e8f64", "type": "concept", "title": "tech stack"}, {"id": "8f8fda4c-a9db-4cc8-b59b-907df8aa374a", "type": "concept", "title": "data flows"}, {"id": "a6bcfe27-de39-4f82-8dd8-807d4d78e8fe", "type": "concept", "title": "platform risk"}, {"id": "e3d03ed6-4ea5-4488-ac9e-3c45a27c5e30", "type": "concept", "title": "policy exposure"}], "description": "Why it matters: Students evaluate the technical infrastructure, platform dependencies, risks, and regulatory constraints."}, {"id": "b564b348-2c44-4a3d-b612-458a3b2e906d", "type": "subtopic", "title": "Strategic recommendation", "children": [{"id": "3c3f5ed2-b5ee-4194-bfe3-ca2200a0737b", "type": "concept", "title": "scenario planning"}, {"id": "49eaf7f2-4c91-47aa-a6b8-957a97a1a370", "type": "concept", "title": "metrics"}, {"id": "625437a2-cb51-42cc-b402-eabd57dac7cc", "type": "concept", "title": "implementation plan"}, {"id": "4094a535-e4f2-4dae-875e-dedc90c1a808", "type": "concept", "title": "executive briefing"}], "description": "Why it matters: Students produce an evidence-based recommendation that balances sustainability, innovation, ethics, and public value."}]}], "dbBacked": true}$etcojson$::jsonb,
