  summary = 'Analyze how economic incentives, technologies, platforms, regulation, and data systems shape communication industries, public culture, labor, access, and democratic life. Students learn to evaluate media business models and design responsible communication technology strategies.',
  data = $etcojson${"slug": "economics-and-technologies-of-communication", "title": "Economics and Technologies of Communication", "description": "Analyze how economic incentives, technologies, platforms, regulation, and data systems shape communication industries, public culture, labor, access, and democratic life. Students learn to evaluate media business models and design responsible communication technology strategies.", "topics": [{"id": "5db24bd2-3df3-437a-81fa-bd7f787798bd", "type": "topic", "title": "Media Industry Structures and Communication Value Chains", "description": "This section maps how communication products move from creation to distribution, monetization, measurement, and governance. Students learn to see media as organized industries.", "children": [{"id": "45329911-ed9c-40c6-8cf1-20bac2bf58ed", "type": "subtopic", "title": "Industry sectors and value chains", "children": [{"id": "b146b82a-23ae-405d-8760-1078cbfc1e8c", "type": "concept", "title": "publishing"}, {"id": "c88c2004-0400-468c-b397-834a583e6309", "type": "concept", "title": "broadcasting"}, {"id": "6fd12a24-c7da-47be-91cb-1713366bea4a", "type": "concept", "title": "film and streaming"}, {"id": "5dfd94ca-cdce-498c-a394-bd45de3543c6", "type": "concept", "title": "audio"}, {"id": "6d6f51e5-3f76-446e-96c9-457556ec3f09", "type": "concept", "title": "social platforms"}], "description": "Why it matters: The point is to understand who creates, finances, packages, distributes, and captures value from communication."}, {"id": "24553fb6-7f27-4f00-a5bd-2294fbde2572", "type": "subtopic", "title": "Production, distribution, and aggregation", "children": [{"id": "3de9386a-f526-4353-afac-a6310ba3a3ca", "type": "concept", "title": "studios"}, {"id": "a2246aea-4ac6-42b5-93c2-63832a8063cb", "type": "concept", "title": "networks"}, {"id": "8a815e5e-4519-46af-80da-35ed1593106f", "type": "concept", "title": "platforms"}, {"id": "d29ea32d-2d44-49fd-9993-3c85c9af5cac", "type": "concept", "title": "app stores"}, {"id": "27f48eb2-44a5-4f53-b2e3-51502f8421cb", "type": "concept", "title": "search and recommendation"}], "description": "Why it matters: Students distinguish the economics of making content from the economics of controlling access and attention."}, {"id": "df2253b0-0892-4d2d-9c26-cc3c23f34bc1", "type": "subtopic", "title": "Stakeholders and incentives", "children": [{"id": "0f9a89a5-a971-49c9-9dfb-bf0ce5f9f1a0", "type": "concept", "title": "creators"}, {"id": "498cac7e-fda1-4fd7-8c1d-0a88b599b12e", "type": "concept", "title": "advertisers"}, {"id": "3fc13e3f-f58b-4b46-9aad-45426a05538c", "type": "concept", "title": "subscribers"}, {"id": "a42deb2f-42e5-4100-a301-838576901d19", "type": "concept", "title": "rights holders"}, {"id": "3b009c6a-588f-4035-999e-5672edabff2f", "type": "concept", "title": "regulators"}], "description": "Why it matters: Industry structure shapes what audiences see and what creators can sustain."}]}, {"id": "8993edea-19b2-4236-a0ca-37b95a29053d", "type": "topic", "title": "Economic Foundations of Media and Information Markets", "description": "Communication markets have unusual economics: high fixed costs, low marginal costs, network effects, public-good features, and attention constraints.", "children": [{"id": "a2e81b9d-1525-4fa0-b35b-f78dcb91a061", "type": "subtopic", "title": "Cost structures", "children": [{"id": "377e0b84-de5e-46f5-8a49-26e8598d8ff2", "type": "concept", "title": "fixed costs"}, {"id": "9ab382d4-1405-45de-8243-d28946e10941", "type": "concept", "title": "marginal cost"}, {"id": "c9666d1a-e175-497e-8b27-f4d3166524f4", "type": "concept", "title": "economies of scale"}, {"id": "042a6bd5-3140-4bc7-b183-b70891d9824d", "type": "concept", "title": "economies of scope"}], "description": "Why it matters: Students learn why information goods scale differently from physical goods."}, {"id": "6919e407-1ed8-4c2d-b1d2-0bc67176cfc2", "type": "subtopic", "title": "Demand and audience behavior", "children": [{"id": "88a9014f-9fde-422f-b934-6c25387af2e7", "type": "concept", "title": "elasticity"}, {"id": "595981a0-2552-4203-ba37-d746d228cda4", "type": "concept", "title": "bundling"}, {"id": "ca468150-307e-44fb-8801-d9332985b806", "type": "concept", "title": "switching costs"}, {"id": "1599d53c-bc80-4689-bd7f-d0aad9e471a5", "type": "concept", "title": "habit formation"}], "description": "Why it matters: Media demand depends on habits, identity, price, convenience, and social influence."}, {"id": "17e0639c-9c44-49ac-b5db-b81538996cad", "type": "subtopic", "title": "Market failures", "children": [{"id": "019a72e0-ac45-4162-a2b0-9d2f696e59a4", "type": "concept", "title": "externalities"}, {"id": "6ef5c223-bae5-4b23-aaef-607d21abd764", "type": "concept", "title": "public goods"}, {"id": "41dec113-312e-4321-b854-50fe1c14c458", "type": "concept", "title": "information asymmetry"}, {"id": "a288a946-2700-4b7f-bd7c-c8f9f6e382b0", "type": "concept", "title": "quality uncertainty"}], "description": "Why it matters: Media markets can underproduce public-interest information and overproduce sensational or addictive content."}]}, {"id": "0cb6d14f-97b5-4d56-91e2-97031a125cec", "type": "topic", "title": "Advertising-Supported Media and the Attention Economy", "description": "Advertising turns audience attention into economic value. Students examine how that model funds media while also shaping content, design, and public life.", "children": [{"id": "230d5ead-a292-4462-92c7-e0ae6dd4cd84", "type": "subtopic", "title": "Advertising markets", "children": [{"id": "b7da9f1e-e95e-410d-a4fe-53deb0b02381", "type": "concept", "title": "CPM"}, {"id": "613adfc0-ebde-495d-8224-16217d20c1f1", "type": "concept", "title": "CPC"}, {"id": "854c0a36-7e71-402d-9cd8-87d5e5ea03a5", "type": "concept", "title": "programmatic advertising"}, {"id": "462f96f4-62e2-4062-a79b-346345f0a211", "type": "concept", "title": "ad exchanges"}], "description": "Why it matters: Students learn how advertisers, publishers, agencies, and platforms buy and sell attention."}, {"id": "eaed74ab-5cb4-4be5-9e00-80357d01e22f", "type": "subtopic", "title": "Attention as scarce resource", "children": [{"id": "b9a7e4f0-38fe-47e7-a30a-ea9e7f2a155a", "type": "concept", "title": "engagement"}, {"id": "54a45123-af4b-4893-bac5-e4824d295367", "type": "concept", "title": "retention"}, {"id": "dd9591dc-975d-4125-a7f7-173de443f6fa", "type": "concept", "title": "notifications"}, {"id": "65e59bbe-48e1-4dc2-b553-35aa91a5416c", "type": "concept", "title": "dark patterns"}], "description": "Why it matters: The course examines design choices that compete for time, emotion, and habit."}, {"id": "05a401b9-d006-4082-afcb-02c4bcf0113a", "type": "subtopic", "title": "Consequences of ad dependence", "children": [{"id": "e44b954f-40a1-4a8c-8031-f33583f6d37c", "type": "concept", "title": "clickbait"}, {"id": "f6b12881-ee45-479e-9a23-931130997898", "type": "concept", "title": "brand safety"}, {"id": "d087fa0a-5d91-4b68-8eab-aad0736b6b6e", "type": "concept", "title": "surveillance advertising"}, {"id": "bad40195-44b0-47f3-b614-67837b90afa1", "type": "concept", "title": "content incentives"}], "description": "Why it matters: Students assess how advertising incentives affect journalism, entertainment, privacy, and civic knowledge."}]}, {"id": "36159215-3994-40fb-b582-3097ab3d8c22", "type": "topic", "title": "Subscription, Paywalls, Bundles, and Direct Revenue Models", "description": "This topic studies how media organizations seek revenue beyond advertising. Students compare subscriptions, bundles, memberships, licensing, patronage, and direct creator support.", "children": [{"id": "e1c50dab-aa42-438a-995a-b4ec28068d9d", "type": "subtopic", "title": "Subscription economics", "children": [{"id": "1376e3ba-c6d2-4797-aae3-c9c06b85bef9", "type": "concept", "title": "churn"}, {"id": "f71d1731-adbd-4914-8199-d0275f491ba5", "type": "concept", "title": "customer lifetime value"}, {"id": "600dde63-abc9-48c9-9440-dcdd67ac5867", "type": "concept", "title": "freemium"}, {"id": "d2314864-775a-40c0-8096-4f0f81f5ae65", "type": "concept", "title": "paywalls"}], "description": "Why it matters: Recurring revenue changes incentives around retention, loyalty, and niche audience value."}, {"id": "e725ff56-59b4-44d8-951a-8e29758892f9", "type": "subtopic", "title": "Bundling and unbundling", "children": [{"id": "91705c3b-216c-4280-a631-5584ca3bb5a3", "type": "concept", "title": "cable bundle"}, {"id": "598ec988-f99d-4384-abab-fe9f61f84715", "type": "concept", "title": "streaming bundles"}, {"id": "4ac9e5c4-6ebb-4bb8-94da-905ae63fc074", "type": "concept", "title": "newsletter stacks"}, {"id": "418480e8-e44a-451c-9a69-ef50a604a031", "type": "concept", "title": "platform packages"}], "description": "Why it matters: Students learn why communication services repeatedly bundle, fragment, and rebundle."}, {"id": "3a32ae08-6be0-4520-bd18-70439e0b58d8", "type": "subtopic", "title": "Membership and patronage", "children": [{"id": "4c5c2b01-dcc2-430f-8447-6937162c558b", "type": "concept", "title": "membership"}, {"id": "02162cb2-10da-4848-8e82-508a488b5ed7", "type": "concept", "title": "crowdfunding"}, {"id": "1c43c338-744b-4846-bd70-2847684cf27a", "type": "concept", "title": "donations"}, {"id": "4585219c-b5a4-43df-bb92-104564cf2da2", "type": "concept", "title": "creator subscriptions"}], "description": "Why it matters: Direct support models can align with communities, but they also create inequality and sustainability questions."}]}, {"id": "9aea6674-f85f-46e0-a964-5bd4170618ba", "type": "topic", "title": "Platform Economics, Network Effects, and Two-Sided Markets", "description": "Platforms coordinate users, creators, advertisers, developers, and institutions. Students learn the economic logic behind platform scale and power.", "children": [{"id": "9ef76b19-00a9-4bc0-9eca-0ea478f00ee1", "type": "subtopic", "title": "Two-sided and multi-sided markets", "children": [{"id": "c0dba2a1-ef78-48db-9745-7eba4571264d", "type": "concept", "title": "cross-side network effects"}, {"id": "d449ac41-46e6-4f0f-b8ff-8074d51ce2c9", "type": "concept", "title": "pricing sides"}, {"id": "fb82c914-9f6c-418a-bece-e76903081c22", "type": "concept", "title": "subsidies"}, {"id": "c48cd09b-6888-4bf1-bfe7-2bb7ae9d452a", "type": "concept", "title": "market thickness"}], "description": "Why it matters: Platforms create value by matching groups whose participation affects each other."}, {"id": "7a1d47cf-c9db-4d92-863c-62700af6b077", "type": "subtopic", "title": "Network effects and lock-in", "children": [{"id": "b6f5df25-aeb4-4230-8b4c-095d9be07ec2", "type": "concept", "title": "direct network effects"}, {"id": "a2c95ebc-5802-4a08-aee0-1a1a06deb1d0", "type": "concept", "title": "indirect network effects"}, {"id": "75b5b77b-9309-4a11-ae13-c54c012f8cb7", "type": "concept", "title": "switching costs"}, {"id": "3e43b16a-e51e-48ce-b5c0-0933b82002cf", "type": "concept", "title": "walled gardens"}], "description": "Why it matters: Scale can improve usefulness while making competition and exit harder."}, {"id": "22912076-74b3-46ca-af86-2ce351a3f539", "type": "subtopic", "title": "Platform governance as business strategy", "children": [{"id": "332f651f-4ee7-4b2d-b655-d06bbe1d5618", "type": "concept", "title": "app store rules"}, {"id": "645beef2-c02f-4513-ade1-8f1a362906d4", "type": "concept", "title": "creator funds"}, {"id": "4f0ac332-0de3-4cc4-8bca-651c55ecaa0d", "type": "concept", "title": "take rates"}, {"id": "bb59eb6f-db3c-4e07-a982-239084b979b8", "type": "concept", "title": "API access"}], "description": "Why it matters: Rules, ranking, moderation, APIs, and fees are part of the platform business model."}]}, {"id": "13bd1e2f-e15c-42d1-b811-266c9aff18a7", "type": "topic", "title": "Datafication, Analytics, and Measurement", "description": "Digital communication is measured continuously. Students learn how metrics are produced, interpreted, gamed, and turned into business or policy decisions.", "children": [{"id": "0568e161-2e6b-4e9a-8ae1-71c455786563", "type": "subtopic", "title": "Audience measurement", "children": [{"id": "f4e3077f-69aa-46bd-881c-5bd38dcfe3fd", "type": "concept", "title": "ratings"}, {"id": "d0ef976b-5ee8-4fca-ac61-277f890c7f15", "type": "concept", "title": "impressions"}, {"id": "8165af7c-faa0-413c-a705-010c2053b75e", "type": "concept", "title": "engagement"}, {"id": "c3509838-46f1-4789-9601-f5ac730a77d0", "type": "concept", "title": "reach and frequency"}], "description": "Why it matters: The point is to understand how media value is quantified and sold."}, {"id": "b9be6af3-1ec5-4f33-997b-3285178c9911", "type": "subtopic", "title": "Analytics for strategy", "children": [{"id": "6638fe32-31ac-43cd-8409-482fc16eea80", "type": "concept", "title": "KPIs"}, {"id": "76ffaa1d-3186-4002-99cb-56379fb6e5f2", "type": "concept", "title": "dashboards"}, {"id": "b6ebb8e1-1c79-48f4-94f9-a8a18d202fca", "type": "concept", "title": "cohorts"}, {"id": "f2b3f72e-426d-4d08-b343-f8d62382138a", "type": "concept", "title": "A/B testing"}], "description": "Why it matters: Students use metrics to evaluate campaigns, products, audiences, and revenue models without confusing metrics with meaning."}, {"id": "0f417ceb-620b-43b6-aaa3-3d0afd725c75", "type": "subtopic", "title": "Measurement limits", "children": [{"id": "4bd53cd4-a4a0-4ea6-9de3-097c5354f5ee", "type": "concept", "title": "vanity metrics"}, {"id": "393b9f64-9da7-4c46-856b-b57ccd5f2810", "type": "concept", "title": "attribution problems"}, {"id": "4469268f-920a-4d72-826b-4f24fc7a1375", "type": "concept", "title": "selection bias"}, {"id": "9a0207a8-d636-4e1c-a978-239e60141a19", "type": "concept", "title": "metric gaming"}], "description": "Why it matters: Metrics can distort behavior and overlook public value, quality, trust, and harm."}]}, {"id": "1fca33b1-8fc5-409f-89ac-eaed8c6ebee7", "type": "topic", "title": "Digital Disruption of Legacy Communication Industries", "description": "This section explains how digital technologies disrupted newspapers, music, television, film, advertising, and publishing. Students learn patterns of technological transition.", "children": [{"id": "ac744604-a03f-4f45-a684-4a86b89200ee", "type": "subtopic", "title": "Disintermediation and reintermediation", "children": [{"id": "c616ccc6-8782-4b2b-9d72-de70c4e85e43", "type": "concept", "title": "Napster and music"}, {"id": "7665e5fd-7e40-426a-b873-f6822c4cc0b3", "type": "concept", "title": "streaming"}, {"id": "35af7a4c-c458-4e41-9763-2ed4560b5c36", "type": "concept", "title": "platform distribution"}, {"id": "2be16fe2-a9be-4433-b41f-9b4f4f08c396", "type": "concept", "title": "creator tools"}], "description": "Why it matters: Digital tools remove some gatekeepers while creating new ones."}, {"id": "72a2c032-03eb-4cea-ab0b-f99a2615ae2d", "type": "subtopic", "title": "Legacy industry adaptation", "children": [{"id": "3c3a6bea-36d2-4c4d-85c1-295681ac1bd3", "type": "concept", "title": "news subscriptions"}, {"id": "f8d9e8d4-52f6-41fd-8fc1-05053e1b0307", "type": "concept", "title": "streaming wars"}, {"id": "c8fbe160-bca2-4cbf-bf17-4053624d8c85", "type": "concept", "title": "podcasting"}, {"id": "c1e63dcc-a5d3-4ad1-9b67-ac29a40c8577", "type": "concept", "title": "digital-first publishing"}], "description": "Why it matters: Students study how old institutions respond through paywalls, mergers, platform partnerships, and product innovation."}, {"id": "07c8d82c-1fcd-479a-9c50-2d29d0e385b3", "type": "subtopic", "title": "Creative destruction and social cost", "children": [{"id": "5d3e4f5b-f471-4d0c-a1c7-b608774c6b8c", "type": "concept", "title": "local news decline"}, {"id": "c77a8533-898d-4c31-b0af-81bfb4f10d03", "type": "concept", "title": "job loss"}, {"id": "553ecd41-5ab8-48bb-b36c-d399567ba3cb", "type": "concept", "title": "new entrants"}, {"id": "bac9450a-fc60-402f-9a2d-28f019539954", "type": "concept", "title": "market volatility"}], "description": "Why it matters: Disruption creates innovation and access, but also labor instability and information gaps."}]}, {"id": "92d5b721-7494-4547-bc4a-110dee8eac31", "type": "topic", "title": "Concentration, Mergers, Antitrust, and Market Power", "description": "Media and technology industries tend toward concentration. Students examine how ownership and market power affect competition, culture, labor, and democracy.", "children": [{"id": "e93bbd7d-0a54-4a74-babe-4f733ea8e977", "type": "subtopic", "title": "Ownership concentration", "children": [{"id": "34f880cf-b730-4416-ae91-ee24f2cd1e23", "type": "concept", "title": "horizontal integration"}, {"id": "cb13094e-d9ca-4613-83dc-006d726886cb", "type": "concept", "title": "vertical integration"}, {"id": "f72f74be-6c01-41ad-a593-dd6e3d9e85ef", "type": "concept", "title": "conglomerates"}, {"id": "679fc74f-5a4a-48d1-b4f8-cb366cf0eadd", "type": "concept", "title": "cross-ownership"}], "description": "Why it matters: Students learn to analyze who owns infrastructure, content, data, and distribution."}, {"id": "dfda93b8-64ab-459a-9a8b-e3cf7743d970", "type": "subtopic", "title": "Antitrust concepts", "children": [{"id": "d80f4d49-5c90-4f47-88c7-7ceb0b6f1fc3", "type": "concept", "title": "market definition"}, {"id": "9091d1c9-713c-4cc4-aac0-5cca6225ec45", "type": "concept", "title": "monopoly power"}, {"id": "a15a4ae6-13d3-4454-bab5-a236f233a350", "type": "concept", "title": "consumer welfare"}, {"id": "b031caa9-00eb-4042-9735-5b40f7eb9c9d", "type": "concept", "title": "innovation harms"}], "description": "Why it matters: The course introduces competition policy tools for evaluating harms beyond simple price effects."}, {"id": "ab1137e6-dab4-410e-a82e-2a47e5a2780c", "type": "subtopic", "title": "Public-interest stakes", "children": [{"id": "53b30254-0f57-4e62-85bc-24eff392e1b6", "type": "concept", "title": "media diversity"}, {"id": "9031e060-a334-4264-9f80-9d752e3878d8", "type": "concept", "title": "editorial independence"}, {"id": "7f4b8550-e798-46a6-b067-f05e248c300b", "type": "concept", "title": "creator leverage"}, {"id": "37413407-2260-4003-b27c-63b3d92070b0", "type": "concept", "title": "platform dominance"}], "description": "Why it matters: Concentration affects diversity, localism, labor bargaining, privacy, and speech power."}]}, {"id": "e0791455-b82e-4590-aec6-6227ccc3b93a", "type": "topic", "title": "Communication Technologies, Infrastructure, and Standards", "description": "Technologies of communication depend on infrastructure: spectrum, broadband, devices, protocols, cloud services, standards, and physical networks.", "children": [{"id": "4db7b440-ab01-48c9-9de0-c22bf03c73be", "type": "subtopic", "title": "Infrastructure layers", "children": [{"id": "ca3ca2b4-d0ff-4cce-9975-f12b9e412829", "type": "concept", "title": "broadband"}, {"id": "dd7f2d6f-8437-41ad-a1f7-5520471e6c7b", "type": "concept", "title": "wireless spectrum"}, {"id": "96eb0fc7-3c15-456c-af0d-222dbddd3e61", "type": "concept", "title": "cloud hosting"}, {"id": "21b783bc-eca7-441c-93b9-342c967fb5d0", "type": "concept", "title": "content delivery networks"}], "description": "Why it matters: Students learn the stack that makes communication possible, from cables to apps."}, {"id": "8c385618-6a13-488a-adae-edfb00672015", "type": "subtopic", "title": "Standards and interoperability", "children": [{"id": "24d4261e-63b0-4cf6-ad3a-d4907ed24768", "type": "concept", "title": "protocols"}, {"id": "33946d10-b780-4703-b852-d39539444e0a", "type": "concept", "title": "APIs"}, {"id": "f0bfd669-6d0c-431d-a41b-22eaf0ea0491", "type": "concept", "title": "interoperability"}, {"id": "859038cd-6298-4cae-b8cb-69ba3d7bb4fc", "type": "concept", "title": "open versus closed systems"}], "description": "Why it matters: Technical standards shape competition, access, and innovation."}, {"id": "a1857f4e-742e-4b4c-8453-4a669cda6351", "type": "subtopic", "title": "Access and reliability", "children": [{"id": "b9d8b477-6a4a-45dc-abc8-5a6ee4d45354", "type": "concept", "title": "digital divide"}, {"id": "b6058600-e8f5-4472-beaa-453fa9d196d3", "type": "concept", "title": "rural broadband"}, {"id": "31ff74be-504e-4fd1-bfe7-0b46773de8c6", "type": "concept", "title": "net neutrality"}, {"id": "a2661251-c3c3-4583-a2c4-51faf4a2a2c1", "type": "concept", "title": "resilience"}], "description": "Why it matters: Infrastructure choices determine who can participate and how resilient communication systems are."}]}, {"id": "ed549cc4-cbf0-4d51-abd1-90c423006f2e", "type": "topic", "title": "Algorithms, AI, Automation, and Recommendation Systems", "description": "Algorithmic systems increasingly decide what is visible, profitable, and actionable. Students study AI and automation as economic, cultural, and governance forces.", "children": [{"id": "10feb5f1-3b7e-4daa-bb28-136e069cd2e3", "type": "subtopic", "title": "Recommendation economics", "children": [{"id": "30d9c492-1ac0-4017-bad9-60dc539f1fd6", "type": "concept", "title": "ranking"}, {"id": "aa129668-a878-4033-86c9-d4c6a4bdce06", "type": "concept", "title": "personalization"}, {"id": "ec3f0d14-78bb-4798-a035-6368b1082686", "type": "concept", "title": "watch time"}, {"id": "aee621e3-bb55-4eca-a74e-0dfa963fa4c0", "type": "concept", "title": "filter bubbles"}], "description": "Why it matters: Recommendation systems allocate attention and revenue across creators, publishers, and publics."}, {"id": "d752c043-7cf4-4560-8eed-4f48c7dd0975", "type": "subtopic", "title": "Automation in media work", "children": [{"id": "ed8337d6-7c71-45ac-a424-aa8d1a9889b4", "type": "concept", "title": "generative AI"}, {"id": "2f956106-379d-4559-84ab-9dff3dbb8f42", "type": "concept", "title": "automated editing"}, {"id": "4e4d4552-f1a8-4b4d-8032-96ef0182c600", "type": "concept", "title": "synthetic media"}, {"id": "1c1c7369-1bde-4bec-aa80-4aa1329a5399", "type": "concept", "title": "workflow automation"}], "description": "Why it matters: AI tools change production, editing, translation, moderation, and analytics."}, {"id": "947019fa-c4d1-4760-a74b-f9e03ac76fca", "type": "subtopic", "title": "Governance and accountability", "children": [{"id": "a40fea1d-b7da-4975-b188-079952036058", "type": "concept", "title": "algorithmic audits"}, {"id": "9cc9fc19-e2d3-448f-8921-871c28b2e4c1", "type": "concept", "title": "explainability"}, {"id": "ece47994-75eb-4cc8-9376-2159c8cffbeb", "type": "concept", "title": "bias"}, {"id": "ac9c8f76-0c46-4689-a4a5-eac5a3023ad1", "type": "concept", "title": "accountability"}], "description": "Why it matters: Students evaluate transparency, bias, auditability, and responsibility in algorithmic systems."}]}, {"id": "297f7e27-9651-456f-bde7-b49271ab3057", "type": "topic", "title": "Technology, Labor, and the Creator Economy", "description": "Digital tools expanded creative opportunity while shifting risk onto individuals. Students examine creator labor, platform dependence, monetization, and professional sustainability.", "children": [{"id": "0484a1b2-aec6-4284-ac7f-44dc43317a14", "type": "subtopic", "title": "Creator business models", "children": [{"id": "d30cb708-eb7c-4e63-bbd8-d8c796a427c8", "type": "concept", "title": "affiliate revenue"}, {"id": "55946523-f69b-4774-b6d2-19fa1733899c", "type": "concept", "title": "sponsorship"}, {"id": "6d42e6eb-dc68-4aaa-bded-8884f345b2fe", "type": "concept", "title": "Patreon-style support"}, {"id": "51388517-3910-45dd-8e38-aaa0382e7f7e", "type": "concept", "title": "merchandise"}], "description": "Why it matters: Students compare how creators earn through ads, sponsorships, subscriptions, merchandise, licensing, and communities."}, {"id": "beb160db-5c8a-4d37-b4b3-dabca73e3076", "type": "subtopic", "title": "Labor and precarity", "children": [{"id": "df12ec83-6a70-4b6a-bd39-c80e778383e4", "type": "concept", "title": "gig labor"}, {"id": "ea9a9c0a-cb44-4062-9e9c-dc781a24bf2e", "type": "concept", "title": "burnout"}, {"id": "c1185c8c-0a60-43e4-ae6c-bd54b86e2a40", "type": "concept", "title": "algorithm dependence"}, {"id": "246b3a84-ad6e-4ef0-81d6-1cf24d8acade", "type": "concept", "title": "income volatility"}], "description": "Why it matters: The creator economy often blends entrepreneurship with instability and unpaid platform work."}, {"id": "c992b6e5-09c9-4f8d-83df-1c75b720c418", "type": "subtopic", "title": "Rights and ownership", "children": [{"id": "5d08ae3d-7dba-4b15-8245-a98429ee0951", "type": "concept", "title": "copyright"}, {"id": "c2bc8b94-728a-467a-a527-e1b964b6828b", "type": "concept", "title": "licensing"}, {"id": "a27ef997-4b5c-4031-b039-9868d028be0a", "type": "concept", "title": "work-for-hire"}, {"id": "0618ac97-fce2-4214-b73c-fe83407cb5a8", "type": "concept", "title": "collective bargaining"}], "description": "Why it matters: Students study intellectual property, contracts, platform terms, and bargaining power."}]}, {"id": "de62a9b0-cbe3-4e21-a5d5-2e13ba75a36b", "type": "topic", "title": "Globalization of Media, Platforms, and Technology Markets", "description": "Communication technologies operate across borders, but regulation, culture, language, and geopolitics vary. Students analyze global platform power and transnational media flows.", "children": [{"id": "a1835cb2-d179-4efc-8a58-856e91acadfe", "type": "subtopic", "title": "Global media markets", "children": [{"id": "d6e46bb7-076f-4e89-8d05-4f5899e0c18c", "type": "concept", "title": "format trade"}, {"id": "ad74b067-ea1f-4477-ba1a-0be90fd7a23d", "type": "concept", "title": "localization"}, {"id": "d8f89528-0820-4317-8563-0485a8b14681", "type": "concept", "title": "global streaming"}, {"id": "94d512eb-cb7a-4cf9-a132-fb62a94a8cee", "type": "concept", "title": "soft power"}], "description": "Why it matters: Students study how content travels through formats, franchises, streaming platforms, and cultural adaptation."}, {"id": "40a9c956-cc98-429f-9883-413fa7a4a60b", "type": "subtopic", "title": "Platform geopolitics", "children": [{"id": "50343a72-8070-4a91-9590-df36be2168af", "type": "concept", "title": "data sovereignty"}, {"id": "6e26b220-abda-4589-a0c2-c8ca064d158d", "type": "concept", "title": "content takedowns"}, {"id": "8f338792-4d30-4db2-9b9b-bad0fd367ad5", "type": "concept", "title": "platform bans"}, {"id": "0031067e-7e78-40e0-9d2d-e68704ed8d3c", "type": "concept", "title": "digital trade"}], "description": "Why it matters: Technology firms face state regulation, data localization, censorship, and trade conflict."}, {"id": "59985d07-b041-481d-b1fc-a3c3ba5abae1", "type": "subtopic", "title": "Unequal global access", "children": [{"id": "de7a578c-7e30-47ed-8766-89498271b119", "type": "concept", "title": "connectivity gaps"}, {"id": "26ccbf35-e302-442f-b2e0-68cb3bb2ef1a", "type": "concept", "title": "outsourced moderation"}, {"id": "46ad2174-0503-4631-ae2a-d5e593974524", "type": "concept", "title": "language markets"}, {"id": "0534744f-3a67-4a3c-a399-818dc7a211af", "type": "concept", "title": "cultural imperialism"}], "description": "Why it matters: Global communication markets reproduce inequalities in infrastructure, language, labor, and representation."}]}, {"id": "9513e953-7a78-4422-bbf0-235539d7ffc1", "type": "topic", "title": "Communication Policy, Regulation, and Governance", "description": "Policy sets the rules for competition, speech, privacy, infrastructure, and public-interest obligations. Students learn to evaluate policy choices as communication design.", "children": [{"id": "75c1d51d-a979-4583-b047-95d8795a4197", "type": "subtopic", "title": "Regulatory institutions", "children": [{"id": "0066c77f-035a-4c5b-a10e-b06a859d553d", "type": "concept", "title": "FCC"}, {"id": "42360de3-7235-40cc-9e2c-ec6e2c2e283b", "type": "concept", "title": "FTC"}, {"id": "988f31b7-e03c-41f0-a9af-a78ccd87cd9d", "type": "concept", "title": "courts"}, {"id": "5f30b93c-4763-4804-9a99-598559980a83", "type": "concept", "title": "EU regulators"}, {"id": "e33da5e1-a6b1-424f-941e-ab52690a55eb", "type": "concept", "title": "standards bodies"}], "description": "Why it matters: Students learn the roles of agencies, courts, legislatures, and international bodies."}, {"id": "d21b05fb-aef8-4c17-8530-33979144cbed", "type": "subtopic", "title": "Policy domains", "children": [{"id": "1bf61fcb-8f4b-499d-aa85-aa857fe72680", "type": "concept", "title": "net neutrality"}, {"id": "6c4ffd2a-9050-4d30-b601-11c9bfe171c2", "type": "concept", "title": "privacy"}, {"id": "1118444c-19cb-455d-b71f-38899894f201", "type": "concept", "title": "copyright"}, {"id": "a2390cfe-488c-4eec-889d-29f49812528f", "type": "concept", "title": "platform liability"}, {"id": "8f242805-3ad9-4aa4-aca3-adb21f429fb8", "type": "concept", "title": "spectrum policy"}], "description": "Why it matters: The course connects media economics to concrete regulatory debates."}, {"id": "47d73153-8a92-46ad-947f-12d877aca091", "type": "subtopic", "title": "Governance tradeoffs", "children": [{"id": "d06eb87a-481b-4940-93eb-52323f82796a", "type": "concept", "title": "cost-benefit analysis"}, {"id": "91ffcc53-aac8-4ede-83dc-838f3a18555f", "type": "concept", "title": "stakeholder analysis"}, {"id": "75d8656b-d9c9-42d7-9bb9-a8a38cb63b37", "type": "concept", "title": "regulatory capture"}, {"id": "4217114a-12d7-41ba-9277-9a0c0b9ee496", "type": "concept", "title": "public interest"}], "description": "Why it matters: Students practice weighing innovation, competition, rights, safety, and public value."}]}, {"id": "b1ad5dc1-8ab2-47cc-9877-9c1c82aaf32a", "type": "topic", "title": "Ethics, Equity, Access, and the Public Interest", "description": "Analysis asks not only what technologies can monetize, but who benefits, who bears risk, and what communication systems owe the public.", "children": [{"id": "0df6af7e-1377-4a1e-bf0a-0c2ff963b22d", "type": "subtopic", "title": "Equity and access", "children": [{"id": "db8470c5-d58d-47ff-8c88-1838361f6407", "type": "concept", "title": "digital divide"}, {"id": "c5b4ce57-acd1-4b60-9ac6-2da22b6db26e", "type": "concept", "title": "accessibility"}, {"id": "0cb9f77f-02c0-48e9-8517-b3626767ab8e", "type": "concept", "title": "language access"}, {"id": "f1873c13-105c-4465-9434-f1ac5e9bb5ea", "type": "concept", "title": "affordability"}], "description": "Why it matters: Students analyze how economic and technical systems include some groups and exclude others."}, {"id": "ca617d2d-f597-433e-a748-5199526563dc", "type": "subtopic", "title": "Privacy and surveillance", "children": [{"id": "0c3f5512-2795-4c33-83cf-ed3fe5301dd3", "type": "concept", "title": "tracking"}, {"id": "f2bf909e-fae4-449b-8611-93809150373b", "type": "concept", "title": "data brokers"}, {"id": "413f5249-9a0a-429e-be05-6ab14420706e", "type": "concept", "title": "behavioral targeting"}, {"id": "eb3690d2-0e6a-40ff-b390-e0b7a3a9a014", "type": "concept", "title": "privacy by design"}], "description": "Why it matters: Data-driven business models raise questions about consent, autonomy, and harm."}, {"id": "14d3d2e9-07c4-4c95-b2e8-6ad4c2308178", "type": "subtopic", "title": "Public-interest media", "children": [{"id": "aab5a069-2a15-4e95-8725-7480413ccf0f", "type": "concept", "title": "public media"}, {"id": "ace20371-1881-4584-985e-b2b016a845cd", "type": "concept", "title": "nonprofit journalism"}, {"id": "7eb77e39-b422-4d45-bae9-92fd8b4ee142", "type": "concept", "title": "community media"}, {"id": "540a10c5-689a-4b9b-a5a7-8e15165c821f", "type": "concept", "title": "media subsidies"}], "description": "Why it matters: Students evaluate models that support journalism, education, civic knowledge, and cultural diversity."}]}, {"id": "5a0b0cbc-f4cc-4107-997e-a4d74a909aa1", "type": "topic", "title": "Applied Media Business and Technology Strategy Lab", "description": "The final lab asks students to apply economic, technical, ethical, and policy analysis to a real communication organization, platform, product, or public-interest problem.", "children": [{"id": "bf69dab5-c821-4524-b856-0dd1e74395d7", "type": "subtopic", "title": "Market and stakeholder analysis", "children": [{"id": "006a8474-58a0-409b-bc7e-ae3fcaec38d6", "type": "concept", "title"